-- Draft starter projects (3 per campaign). Safe to re-run. Edit brand names, add images and tick Published in /admin/portfolio.
insert into projects (slug, title, client_name, industry, campaign_type, service_category, description, objective, creative_direction, deliverables, related_services, related_package, is_concept, published, featured, sort_order) values
('black-friday-fashion-sale', 'Black Friday Fashion Sale Campaign', 'Your Brand Name', 'fashion', 'black-friday', 'banner-design', 'A high-impact Black Friday campaign for a fashion brand: a homepage banner and matching flyer built around one clear, bold offer.', 'Drive traffic to the sale collection and make the discount instantly clear to first-time visitors.', 'Black, white and electric lime with oversized type and a single focal offer. Layouts built for both desktop and mobile.', array['Homepage banner (desktop and mobile)','Sale flyer','Instagram post and story'], array['banner-design','flyer-design','social-media-design'], 'pro-campaign', true, false, false, 0),
('black-friday-electronics-deals', 'Black Friday Electronics Deals Banner', 'Your Brand Name', 'electronics', 'black-friday', 'banner-design', 'A deals-focused banner set for an electronics and gadgets store, highlighting hero products and the discount depth.', 'Highlight top deals above the fold and guide shoppers to the doorbuster collection.', 'Dark, high-contrast layout with product-forward composition, clear price callouts and a strong call to action.', array['Homepage hero banner','Collection page banner','Promotional email copy'], array['banner-design','email-copywriting'], 'growth-campaign', true, false, false, 1),
('cyber-monday-beauty-promo', 'Black Friday & Cyber Monday Beauty Promotion', 'Your Brand Name', 'beauty', 'black-friday', 'banner-design', 'A two-part promotion for a beauty and skincare brand, with Black Friday creative and Cyber Monday follow-on variations.', 'Extend the sales momentum past Black Friday with consistent follow-on creative.', 'A clean, premium look with soft product imagery and restrained accent colour, adapted into Cyber Monday variations.', array['Black Friday banner','Cyber Monday variation','Social media set'], array['banner-design','social-media-design'], 'complete-campaign', true, false, false, 2),
('christmas-gift-guide', 'Christmas Gift Guide Campaign', 'Your Brand Name', 'accessories', 'christmas', 'flyer-design', 'An elegant gift guide for a jewellery and accessories brand, organised by recipient and budget.', 'Help shoppers find gifts quickly and lift basket size with curated suggestions.', 'Rich reds, gold and deep green with elegant product compositions and generous whitespace.', array['Gift guide flyer','Homepage banner','Festive social posts'], array['flyer-design','banner-design','social-media-design'], 'pro-campaign', true, false, false, 3),
('christmas-home-bundles', 'Christmas Home Bundles Promotion', 'Your Brand Name', 'home', 'christmas', 'banner-design', 'A festive bundle promotion for a home and lifestyle store, showing gift sets as ready-to-give options.', 'Make bundles easy to understand and increase average order value during the festive season.', 'Warm, cosy palette with clear bundle pricing and lifestyle-led composition.', array['Bundle banner','Promotional flyer','Christmas sale email copy'], array['banner-design','flyer-design','email-copywriting'], 'growth-campaign', true, false, false, 4),
('christmas-fashion-festive-edit', 'Festive Fashion Edit Social Campaign', 'Your Brand Name', 'fashion', 'christmas', 'social-media-design', 'A festive social media campaign for a fashion brand, from countdown posts to last-order reminders.', 'Keep the brand visible through the festive weeks and drive last-minute orders.', 'A consistent festive look across posts, stories and carousels, with clear shipping-deadline messaging.', array['Instagram posts','Stories','Carousel'], array['social-media-design'], 'starter-creative', true, false, false, 5),
('new-year-fresh-start-sale', 'New Year Fresh Start Sale Banner', 'Your Brand Name', 'lifestyle', 'new-year', 'banner-design', 'A fresh-start sale banner for a lifestyle brand, built around new routines and new-year offers.', 'Open the year with momentum and bring shoppers back after the festive season.', 'Bright, optimistic colour with energetic type and a clear sale message.', array['Homepage banner','Mobile banner','Promotional email copy'], array['banner-design','email-copywriting'], 'growth-campaign', true, false, false, 6),
('new-year-collection-launch', 'New Year New Collection Launch', 'Your Brand Name', 'fashion', 'new-year', 'banner-design', 'A launch campaign for a first-of-the-year collection, across banner, flyer and social creatives.', 'Introduce the new collection and drive early traffic and sales.', 'Modern, celebratory styling with strong product focus and a consistent look across every asset.', array['Launch banner','Launch flyer','Social media set'], array['banner-design','flyer-design','social-media-design'], 'pro-campaign', true, false, false, 7),
('new-year-gadget-offers', 'New Year Gadget Offers Campaign', 'Your Brand Name', 'electronics', 'new-year', 'banner-design', 'A new-year offers campaign for an electronics store, with banners and social creatives for headline deals.', 'Promote new-year offers on popular gadgets and clear remaining seasonal stock.', 'Fresh, tech-forward palette with sharp product shots and clear price callouts.', array['Offers banner','Product promo banners','Instagram posts'], array['banner-design','social-media-design'], 'starter-creative', true, false, false, 8)
on conflict (slug) do nothing;
-- Run AFTER 0003_seed_campaign_projects.sql.
-- Publishes the 9 starter projects with temporary cover images (replace them in /admin when your designs are ready).
-- Brand name is cleared so "Your Brand Name" never shows publicly; add the real brand in /admin.
update projects set published = true, client_name = null
where slug in (
  'black-friday-fashion-sale','black-friday-electronics-deals','cyber-monday-beauty-promo',
  'christmas-gift-guide','christmas-home-bundles','christmas-fashion-festive-edit',
  'new-year-fresh-start-sale','new-year-collection-launch','new-year-gadget-offers'
);
-- Featured: first project of each campaign
update projects set featured = true where slug in ('black-friday-fashion-sale','christmas-gift-guide','new-year-fresh-start-sale');
-- Temporary covers (files in the site's /public/images folder). New Year projects keep the built-in artwork until you upload covers.
update projects set cover_image_path = '/images/hero-banner.webp'       where slug in ('black-friday-fashion-sale','black-friday-electronics-deals');
update projects set cover_image_path = '/images/hero-blackfriday.jpg'   where slug = 'cyber-monday-beauty-promo';
update projects set cover_image_path = '/images/hero-gifting.webp'      where slug in ('christmas-gift-guide','christmas-home-bundles','christmas-fashion-festive-edit');
